  messagingSenderId: "651996830719",
  appId: "1:651996830719:web:b2663d1a77059c5d9ba5ca",
  measurementId: "G-NX9H4MWH8L"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Export modular instances
export const auth = getAuth(app);
export const db = getFirestore(app);
export const Firebase = { auth, db };
